echo "--- via traefik http (expect redirect to https) ---"; curl -sS -o /dev/null -w "HTTP %{http_code} -> %{redirect_url}
" --max-time 15 http://127.0.0.1/ ; echo "curl_exit=$?"; echo "--- API measurements endpoint ---"; curl -sS -o /dev/null -w "HTTP %{http_code}
" --max-time 15 -X POST http://127.0.0.1/api/v1/node/measurements; echo "curl_exit=$?"; echo "--- swagger docs ---"; curl -sS -o /dev/null -w "HTTP %{http_code}
" --max-time 15 http://127.0.0.1/administration/docs/

echo "--- frontend (via traefik, Host: localhost, expect 301 to https) ---"; curl -sS -o /dev/null -w "HTTP %{http_code} -> %{redirect_url}
" --max-time 15 -H "Host: localhost" http://127.0.0.1/; echo "curl_exit=$?"; echo "--- swagger with no auth (expect 401) ---"; curl -sS -o /dev/null -w "HTTP %{http_code}
" --max-time 15 -H "Host: localhost" http://127.0.0.1/administration/docs/; echo "--- direct to web container: frontend ---"; docker exec yii2_vue_dash_container curl -sS -o /dev/null -w "HTTP %{http_code}
" --max-time 15 http://127.0.0.1/; echo "--- direct to web container: swagger no auth ---"; docker exec yii2_vue_dash_container curl -sS -o /dev/null -w "HTTP %{http_code}
" --max-time 15 http://127.0.0.1/administration/docs/

docker exec yii2_vue_dash_container curl -sS --max-time 15 -X POST -H "Content-Type: application/json" -d '{}' http://127.0.0.1/api/v1/node/measurements; echo; echo "--- adapter health ---"; docker exec iothubsh_adapter curl -sS -o /dev/null -w "HTTP %{http_code}
" --max-time 15 http://127.0.0.1:8000/health 2>/dev/null || docker exec iothubsh_adapter curl -sS -o /dev/null -w "HTTP %{http_code}
" --max-time 15 http://127.0.0.1:8000/ ; echo "--- webhook/config route via traefik (Host: localhost) ---"; curl -sS -o /dev/null -w "HTTP %{http_code}
" --max-time 15 -H "Host: localhost" http://127.0.0.1/webhook/config; echo "--- final container status ---"; cd /workspace && docker compose ps --format "table {{.Name}}	{{.Status}}"

docker exec iothubsh_adapter python -c "
import urllib.request
try:
    r = urllib.request.urlopen('http://127.0.0.1:8000/docs', timeout=10)
    print('docs:', r.status)
except Exception as e:
    print('docs error:', e)
try:
    r = urllib.request.urlopen('http://127.0.0.1:8000/openapi.json', timeout=10)
    print('openapi:', r.status)
except Exception as e:
    print('openapi error:', e)
" 2>&1; echo "adapter_logs:"; cd /workspace && docker compose logs --tail=5 iothubsh-adapter 2>&1

